<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api } from '../api'

type FileRecord = { file_id: string; original_name: string }
type InspectionColumn = { header: string; business_hint?: string | null }
type FieldSide = { fields: string[]; combine: 'concat' | 'coalesce' | 'best_of'; separator: string; pipeline: Array<Record<string, unknown>> }
type Rule = { id: string; source: FieldSide; target: FieldSide; matcher: string; weight: number; critical: boolean }

const route = useRoute(), router = useRouter()
const active = ref(0), draftId = ref(''), name = ref('')
const source = ref<FileRecord | null>(null), target = ref<FileRecord | null>(null)
const sourceColumns = ref<string[]>([]), targetColumns = ref<string[]>([])
const groupCodeColumn = ref(''), catalogVersionId = ref('')
const rules = ref<Rule[]>([]), scopeMode = ref<'GLOBAL' | 'STRICT' | 'MAPPED'>('GLOBAL')
const successThreshold = ref(88), reviewThreshold = ref(75), topN = ref(5)
const advanced = ref(false), task = ref<any>(null), busy = ref(false)
let saveTimer: number | undefined
const summary = computed(() => `参与字段：${rules.value.length} 个｜总权重：${rules.value.reduce((sum, rule) => sum + Number(rule.weight || 0), 0)}（运行时归一）｜自动匹配阈值：${successThreshold.value} 分｜人工确认区间：${reviewThreshold.value}～${successThreshold.value} 分｜候选输出：Top ${topN.value}`)

function columnsFromInspection(inspection: any): InspectionColumn[] { return inspection.sheets.find((item: any) => item.sheet_name === inspection.recommended_sheet)?.columns ?? [] }
async function loadFile(fileId: string, kind: 'source' | 'target'): Promise<void> { const response = (await api.get(`/files/${fileId}/inspection`)).data; const columns = columnsFromInspection(response.inspection); if (kind === 'source') { source.value = response.file; sourceColumns.value = columns.map((column) => column.header) } else { target.value = response.file; targetColumns.value = columns.map((column) => column.header); if (!groupCodeColumn.value) groupCodeColumn.value = columns.find((column) => column.business_hint === 'group_code')?.header ?? targetColumns.value[0] ?? '' } }
async function ensureDraft(): Promise<void> { if (draftId.value) return; const draft = (await api.post('/task-drafts', { name: name.value || '未命名匹配任务' })).data; draftId.value = draft.draft_id; await router.replace({ path: '/tasks/new', query: { draft: draftId.value } }) }
async function upload(kind: 'source' | 'target', selected: any): Promise<void> { busy.value = true; try { const form = new FormData(); form.append('role', kind); form.append('file', selected.raw); const response = (await api.post('/files/upload', form)).data; const columns = columnsFromInspection(response.inspection); if (kind === 'source') { source.value = response.file; sourceColumns.value = columns.map((column) => column.header) } else { target.value = response.file; targetColumns.value = columns.map((column) => column.header); groupCodeColumn.value = columns.find((column) => column.business_hint === 'group_code')?.header ?? targetColumns.value[0] ?? '' } } finally { busy.value = false } }
function defaultRule(): Rule { return { id: `rule_${rules.value.length + 1}`, source: { fields: sourceColumns.value.slice(0, 1), combine: 'concat', separator: ' ', pipeline: [] }, target: { fields: targetColumns.value.slice(0, 1), combine: 'concat', separator: ' ', pipeline: [] }, matcher: 'fuzzy', weight: rules.value.length ? 50 : 80, critical: false } }
async function nextStepOne(): Promise<void> { await ensureDraft(); if (!source.value || !target.value || !groupCodeColumn.value) return; if (!catalogVersionId.value) { const catalog = (await api.post('/catalogs', { name: `${name.value || '任务'}-集团码目录`, source_file_id: target.value.file_id, group_code_column: groupCodeColumn.value })).data; catalogVersionId.value = catalog.version_id } await api.put(`/task-drafts/${draftId.value}/data`, { source_file_id: source.value.file_id, catalog_version_id: catalogVersionId.value, template_profile_id: null, template_profile_version: null }); if (!rules.value.length) rules.value = [defaultRule()]; active.value = 1; await saveRules() }
function document(): Record<string, unknown> { return { scope_mode: scopeMode.value, rules: rules.value, decision: { success_threshold: successThreshold.value, review_enabled: true, review_threshold: reviewThreshold.value, top_n: topN.value }, advanced: {} } }
async function saveRules(): Promise<void> { if (!draftId.value || active.value !== 1 || !rules.value.length) return; await api.put(`/task-drafts/${draftId.value}/rules`, document()) }
function scheduleSave(): void { if (saveTimer) window.clearTimeout(saveTimer); saveTimer = window.setTimeout(() => void saveRules(), 500) }
function addRule(): void { rules.value.push(defaultRule()) }
function removeRule(index: number): void { rules.value.splice(index, 1) }
async function start(): Promise<void> { await saveRules(); task.value = (await api.post(`/task-drafts/${draftId.value}/start`)).data; active.value = 2; await router.replace(`/tasks/${task.value.task_id}`) }
async function restoreDraft(id: string): Promise<void> { const draft = (await api.get(`/task-drafts/${id}`)).data; draftId.value = draft.draft_id; name.value = draft.name; if (draft.source_file_id) await loadFile(draft.source_file_id, 'source'); if (draft.catalog_version_id) { const catalog = (await api.get(`/catalogs/versions/${draft.catalog_version_id}`)).data; catalogVersionId.value = catalog.version_id; groupCodeColumn.value = catalog.group_code_column; await loadFile(catalog.source_file_id, 'target') } const config = draft.config_document ?? {}; if (Array.isArray(config.rules) && config.rules.length) { rules.value = config.rules; scopeMode.value = config.scope_mode ?? 'GLOBAL'; successThreshold.value = config.decision?.success_threshold ?? 88; reviewThreshold.value = config.decision?.review_threshold ?? 75; topN.value = config.decision?.top_n ?? 5 } active.value = Math.max(0, Number(draft.current_step ?? 1) - 1) }
watch([rules, scopeMode, successThreshold, reviewThreshold, topN], scheduleSave, { deep: true })
onMounted(async () => { if (route.params.taskId) { try { task.value = (await api.get(`/tasks/${route.params.taskId}`)).data; name.value = task.value.name; active.value = 2 } catch { await router.push('/tasks') } return } const draft = typeof route.query.draft === 'string' ? route.query.draft : ''; if (draft) { try { await restoreDraft(draft) } catch { await router.replace('/tasks/new') } } })
</script>
<template><div><div class="toolbar"><div><h2>{{ name || task?.name || '新建匹配任务' }}</h2><p>五步连续完成，不要求先发布匹配方案。</p></div></div><el-steps :active="active"><el-step title="选择数据"/><el-step title="确认匹配规则"/><el-step title="比对计算"/><el-step title="人工处理"/><el-step title="生成结果"/></el-steps><div v-if="active===0" class="panel"><h3>1. 选择数据</h3><el-input v-model="name" placeholder="任务名称"/><div class="uploads"><div><b>客户物料数据</b><el-upload :auto-upload="false" :show-file-list="false" :on-change="(file:any)=>upload('source',file)"><el-button>选择 Excel / CSV</el-button></el-upload><span>{{source?.original_name}}</span></div><div><b>集团码数据</b><el-upload :auto-upload="false" :show-file-list="false" :on-change="(file:any)=>upload('target',file)"><el-button>选择 Excel / CSV</el-button></el-upload><span>{{target?.original_name}}</span><el-select v-if="targetColumns.length" v-model="groupCodeColumn" placeholder="确认集团码列"><el-option v-for="column in targetColumns" :key="column" :label="column" :value="column"/></el-select></div></div><div class="actions"><el-button type="primary" :loading="busy" :disabled="!name||!source||!target||!groupCodeColumn" @click="nextStepOne">下一步：确认匹配规则</el-button></div></div><div v-else-if="active===1" class="panel"><h3>2. 确认匹配规则</h3><h4>A. 匹配范围</h4><el-radio-group v-model="scopeMode"><el-radio-button value="GLOBAL">全库匹配</el-radio-button><el-radio-button value="STRICT">同组匹配</el-radio-button><el-radio-button value="MAPPED">分类映射匹配</el-radio-button></el-radio-group><h4>B. 字段对应与重要程度</h4><el-table :data="rules"><el-table-column label="客户字段组合" min-width="220"><template #default="scope"><el-select v-model="scope.row.source.fields" multiple collapse-tags><el-option v-for="column in sourceColumns" :key="column" :label="column" :value="column"/></el-select></template></el-table-column><el-table-column label="集团字段组合" min-width="220"><template #default="scope"><el-select v-model="scope.row.target.fields" multiple collapse-tags><el-option v-for="column in targetColumns" :key="column" :label="column" :value="column"/></el-select></template></el-table-column><el-table-column label="客户组合方式" min-width="160"><template #default="scope"><el-select v-model="scope.row.source.combine"><el-option label="拼接" value="concat"/><el-option label="第一个有效值" value="coalesce"/><el-option label="多个比较取最高分" value="best_of"/></el-select></template></el-table-column><el-table-column label="集团组合方式" min-width="160"><template #default="scope"><el-select v-model="scope.row.target.combine"><el-option label="拼接" value="concat"/><el-option label="第一个有效值" value="coalesce"/><el-option label="多个比较取最高分" value="best_of"/></el-select></template></el-table-column><el-table-column label="匹配方式" min-width="130"><template #default="scope"><el-select v-model="scope.row.matcher"><el-option label="完全一致" value="exact"/><el-option label="包含" value="contains"/><el-option label="模糊相似" value="fuzzy"/><el-option label="语义相似" value="semantic"/><el-option label="综合" value="hybrid"/></el-select></template></el-table-column><el-table-column label="权重 0～100" width="150"><template #default="scope"><el-input-number v-model="scope.row.weight" :min="0" :max="100"/></template></el-table-column><el-table-column label="关键字段" width="100"><template #default="scope"><el-switch v-model="scope.row.critical"/></template></el-table-column><el-table-column label="操作" width="80"><template #default="scope"><el-button link type="danger" @click="removeRule(scope.$index)">删除</el-button></template></el-table-column></el-table><el-button link @click="addRule">+ 添加字段对应</el-button><h4>C. 判定阈值</h4><div class="threshold"><span>自动匹配成功阈值</span><el-input-number v-model="successThreshold" :min="1" :max="100"/><span>人工确认下限</span><el-input-number v-model="reviewThreshold" :min="0" :max="99"/><span>TopN</span><el-input-number v-model="topN" :min="1" :max="50"/></div><h4 class="click" @click="advanced=!advanced">D. 高级处理（{{advanced?'收起':'展开'}}）</h4><div v-if="advanced" class="muted">默认 identity；大小写、标点、同义词、空值、标准号、尺寸、单位和数值容差均须字段级显式启用。本阶段已实现后端显式流水线契约，完整可视化操作符编辑器将在后续切片补齐。</div><el-alert :title="summary" :closable="false"/><div class="actions"><el-button @click="active=0">上一步</el-button><el-button type="primary" :disabled="!rules.length||reviewThreshold>=successThreshold" @click="start">下一步：开始比对</el-button></div></div><div v-else class="panel"><h3>3. 比对计算</h3><el-alert title="配置已冻结为不可变 config_snapshot；正式匹配执行器尚未在本切片接入，任务保持 PENDING，不伪造运行结果。" type="warning" :closable="false"/><el-steps direction="vertical"><el-step title="数据准备"/><el-step title="向量化处理"/><el-step title="候选比对"/><el-step title="精细评分"/><el-step title="结果整理"/></el-steps><p>配置 SHA-256：<code>{{task?.config_sha256}}</code></p></div></div></template>
